      <label for="snapshot-from">From</label>
      <input id="snapshot-from" type="date" data-testid="snapshot-from" #snapshotFrom />
      <label for="snapshot-to">To (blank: now)</label>
      <input id="snapshot-to" type="date" data-testid="snapshot-to" #snapshotTo />
      <button type="button" data-testid="snapshot-compare"
              (click)="compareSnapshots(snapshotFrom.value, snapshotTo.value)">Compare</button>
      <ul>
        @for (l of snapshotComparison(); track $index) {
